#ifndef FLASH_HPP_
#define FLASH_HPP_

#include "system.hpp"
#include "flash_config.h"
#include <string.h>

#if !defined(STM32_FLASH_CONFIG_FORMAT) || STM32_FLASH_CONFIG_FORMAT != 3
#error "Flash requires the format 3 configuration generated by the updated base"
#endif

#if defined(STM32F7) || defined(STM32F4)
	using status_t = uint8_t;
#elif defined(STM32G0)
	using status_t = uint64_t;
#else
#error "Flash driver supports STM32F4, STM32F7 and STM32G0 only"
#endif
// Blocking operations: call from the main loop, with SysTick running.
// Do not call from interrupts or critical sections; the driver does not mask IRQs.
class flash_base
{
private:
	static SysStatus program(uint32_t addr, const void* data, uint32_t bytes, uint32_t width);
public:
	enum class bank_type
	{
		SINGLE_BANK,
		DUAL_BANK
	};

	// The default follows the mode selected by project.json/device geometry.
	static SysInitStatus init(bank_type tb = FLASH_DUAL_BANK ? bank_type::DUAL_BANK : bank_type::SINGLE_BANK);
	static SysStatus enable_access();
	static bool ready();
	static SysStatus erase_sector(uint32_t sector);
	static SysStatus mass_erase(uint8_t bank);
	static void clear_errors();

	// Raw read: the caller supplies a valid, aligned address in ready Flash.
	template<typename T>
	static inline T read(uint32_t addr) { return *reinterpret_cast<const volatile T*>(addr); }

	// size is the element count. On G0 the last 8-byte block is padded with FF.
	// Programming a buffer is not atomic; inspect the returned status.
	template<typename T>
	static SysStatus write(uint32_t addr, const T* data, uint32_t size = 1);
};

class flash_data : private flash_base
{

public:

	enum class Data_Status : status_t
	{
		NO_DATA = static_cast<status_t>(-1),
#if defined(STM32G0)
		// Keep the agreed status encoding for the hardware check. On G0,
		// a second nonzero programming of this ECC block can raise PROGERR.
		DATA_WRITING = 0x00FFFFFFFFFFFFFFULL,
#else
		DATA_WRITING = 0x7F,
#endif
		DATA_OK = static_cast<status_t>(static_cast<status_t>(-1) >> (sizeof(status_t) * 4)),
		DATA_CORRUPT = 0x1,
		DATA_NOT_VALID = 0
	};

	flash_data(uint32_t sec, uint8_t *_data, uint32_t sz) :
		sector(sec),
		offset(0),
		next_offset(0),
		stride(0),
		status(Data_Status::NO_DATA),
		initialized(false),
		data(_data),
		size(sz)
	{}

	SysInitStatus SetUp(bank_type tb = FLASH_DUAL_BANK ? bank_type::DUAL_BANK : bank_type::SINGLE_BANK);

	Data_Status read_data();
	SysStatus write_data();

private:
	uint32_t sector;
	uint32_t offset;
	uint32_t next_offset;
	uint32_t stride;
	Data_Status status;
	bool initialized;

	uint8_t *data;
	uint32_t size;

	void find_offset();

};

template<typename T>
SysStatus flash_base::write(uint32_t addr, const T* data, uint32_t size)
{
	static_assert(sizeof(T) == 1 || sizeof(T) == 2 || sizeof(T) == 4 || sizeof(T) == 8);
	if (size > UINT32_MAX / sizeof(T)) return SysStatus::Error;
	return program(addr, data, size * static_cast<uint32_t>(sizeof(T)), sizeof(T));
}

#endif
